"use client";

import React, { useState } from "react";
import Image from "next/image";
import styles from "./page.module.css";

export default function Home() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [game, setGame] = useState(null);

  async function createNewGame() {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch("http://127.0.0.1:8000/game/new/", {
        method: "POST",
        headers: { Accept: "application/json" },
      });

      if (!res.ok) {
        const errJson = await res.json().catch(() => null);
        throw new Error((errJson && errJson.error) || `HTTP ${res.status}`);
      }

      const data = await res.json();
      setGame(data);
    } catch (e) {
      setError(String(e.message || e));
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className={styles.page}>
      <main className={styles.main}>
        <h1>Hangman Game</h1>
        <div style={{ marginTop: 16 }}>
          <button onClick={createNewGame} disabled={loading}>
            {loading ? "Starting..." : "Start New Game"}
          </button>
        </div>

        {error && (
          <div style={{ color: "red", marginTop: 12 }}>Error: {error}</div>
        )}

        {game && (
          <div style={{ marginTop: 12 }}>
            <strong>Game started:</strong>
            <div>game_id: {game.game_id}</div>
            <div>word: {game.guessed_word}</div>
            <div>Guesses Left: {game.guesses_left}</div>
          </div>
        )}
      </main>

      <div className={styles.footer}>
        <p>Author: Jesse Osrecak</p>
      </div>
    </div>
  );
}
